'use client'

import { useEffect, useRef } from 'react'
import { usePathname } from 'next/navigation'

export function NavigationEvents() {
  const pathname = usePathname()
  const navDirection = useRef<'forward' | 'back'>('forward')

  useEffect(() => {
    const handlePopState = () => {
      navDirection.current = 'back'
    }

    window.addEventListener('popstate', handlePopState)
    return () => window.removeEventListener('popstate', handlePopState)
  }, [])

  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      const link = (e.target as HTMLElement).closest('a[href]') as HTMLAnchorElement | null
      if (!link) return

      const href = link.getAttribute('href')
      if (!href || href.startsWith('http') || href.startsWith('//') || link.target === '_blank') return

      const url = new URL(href, window.location.origin)
      if (url.origin !== window.location.origin) return

      navDirection.current = 'forward'

      const supportsViewTransition = 'startViewTransition' in document
      if (!supportsViewTransition) return

      e.preventDefault()

      document.documentElement.dataset.navDirection = navDirection.current

      const transition = document.startViewTransition(() => {
        window.location.href = href
      })

      transition.finished.then(() => {
        delete document.documentElement.dataset.navDirection
      })
    }

    const handlePopStateAndTransition = () => {
      const supportsViewTransition = 'startViewTransition' in document
      if (!supportsViewTransition) return

      document.documentElement.dataset.navDirection = 'back'

      document.startViewTransition(() => {})
    }

    document.addEventListener('click', handleClick)
    window.addEventListener('popstate', handlePopStateAndTransition)

    return () => {
      document.removeEventListener('click', handleClick)
      window.removeEventListener('popstate', handlePopStateAndTransition)
    }
  }, [])

  return null
}

