'use client'

import { useEffect } from 'react'

export function NavigationEvents() {
  useEffect(() => {
    const supportsTransition = 'startViewTransition' in document
    if (!supportsTransition) return

    const handleClick = (e: MouseEvent) => {
      const link = (e.target as HTMLElement).closest('a[href]') as HTMLAnchorElement | null
      if (!link) return
      const href = link.getAttribute('href')
      if (!href || href.startsWith('http') || href.startsWith('//') || link.target === '_blank') return
      const url = new URL(href, window.location.origin)
      if (url.origin !== window.location.origin) return
      document.documentElement.dataset.navDirection = 'forward'
    }

    const origStartViewTransition = document.startViewTransition.bind(document)
    document.startViewTransition = function (cb) {
      const vt = origStartViewTransition(cb)
      vt.finished.then(() => {
        delete document.documentElement.dataset.navDirection
      })
      return vt
    }

    document.addEventListener('click', handleClick, true)
    return () => {
      document.removeEventListener('click', handleClick, true)
      document.startViewTransition = origStartViewTransition
    }
  }, [])

  return null
}

