'use client'

import { useEffect, useRef, useState, type ReactNode } from 'react'

export function SuspenseTransition({
  children,
  fallback,
  transitionName,
}: {
  children: ReactNode
  fallback: ReactNode
  transitionName: string
}) {
  const [showContent, setShowContent] = useState(false)
  const pendingResolve = useRef(false)

  if (!showContent && !pendingResolve.current) {
    pendingResolve.current = true
    if (typeof window !== 'undefined') {
      queueMicrotask(() => {
        if (
          'startViewTransition' in document &&
          !window.matchMedia('(prefers-reduced-motion: reduce)').matches
        ) {
          document.startViewTransition(() => setShowContent(true))
        } else {
          setShowContent(true)
        }
      })
    }
  }

  const viewTransitionStyle = { viewTransitionName: transitionName }

  if (!showContent) {
    return <div style={viewTransitionStyle}>{fallback}</div>
  }

  return <div style={viewTransitionStyle}>{children}</div>
}

