'use client'

import { useRouter } from 'next/navigation'
import { useEffect } from 'react'

let navDirection: 'forward' | 'back' = 'back'

export function NavigationEvents() {
  const router = useRouter()

  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      const link = (e.target as HTMLElement).closest('a[href]') as HTMLAnchorElement | null
      if (!link) return
      const href = link.getAttribute('href')
      if (!href || href.startsWith('http') || href.startsWith('//') || link.target === '_blank')
        return
      const url = new URL(href, window.location.origin)
      if (url.origin !== window.location.origin) return
      navDirection = 'forward'
    }

    document.addEventListener('click', handleClick, true)
    return () => document.removeEventListener('click', handleClick, true)
  }, [])

  useEffect(() => {
    const supportsVT = 'startViewTransition' in document
    if (!supportsVT) return

    const origPush = router.push.bind(router) as typeof router.push
    const origReplace = router.replace.bind(router) as typeof router.replace

    const wrapWithVT = (
      fn: (href: string, options?: any) => void,
      href: string,
      options?: any,
    ) => {
      document.documentElement.dataset.navDirection = navDirection

      const transition = document.startViewTransition(() => {
        return new Promise<void>((resolve) => {
          const observer = new MutationObserver(() => {
            requestAnimationFrame(() => {
              requestAnimationFrame(() => {
                observer.disconnect()
                resolve()
                navDirection = 'back'
              })
            })
          })
          observer.observe(document.body, { childList: true, subtree: true })
          fn(href, options)
        })
      })

      transition.finished.then(() => {
        delete document.documentElement.dataset.navDirection
        navDirection = 'back'
      })
    }

    router.push = ((href: string, options?: any) => {
      wrapWithVT(origPush, href, options)
    }) as typeof router.push

    router.replace = ((href: string, options?: any) => {
      wrapWithVT(origReplace, href, options)
    }) as typeof router.replace

    return () => {
      router.push = origPush
      router.replace = origReplace
    }
  }, [router])

  return null
}

